from pathlib import Path
import base64,zlib,json,runpy
payload=''
files=json.loads(zlib.decompress(base64.b64decode(payload)).decode('utf-8'))
for name,text in files.items():
    p=Path(name); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
runpy.run_path('.changes/apply_v0613_inner.py',run_name='__main__')
